#include <bits/stdc++.h>
using namespace std;

struct InputReader {
    std::istream& stream;
    uint8_t buf[1024];
    int curChar = 0, numChars = 0;

    InputReader(std::istream& s) : stream(s) {}

    int read() {
        if (numChars == -1) throw std::runtime_error("Input error");
        if (curChar >= numChars) {
            curChar = 0;
            numChars = stream.readsome(reinterpret_cast<char*>(buf), sizeof(buf));
            if (numChars == 0) return -1;
        }
        return buf[curChar++];
    }

    int nextInt() {
        int c;
        for (c = read(); isSpaceChar(c); c = read());
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        while (c >= '0' && c <= '9') {
            res = res * 10 + (c - '0');
            c = read();
        }
        return res;
    }

    std::string next() {
        int c;
        while (isSpaceChar(c = read()));
        std::string result;
        do {
            result.push_back(c);
            c = read();
        } while (c != -1 && !isSpaceChar(c));
        return result;
    }

    static bool isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
};

struct OutputWriter {
    std::ostream& out;
    OutputWriter(std::ostream& os) : out(os) {}
    void println(int i) { out << i << "\n"; }
    void close() {}
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    InputReader in(cin);
    OutputWriter out(cout);

    int n = in.nextInt();

    std::string c = in.next();

    int cv = 0, ck = 0, cs = 0;

    std::vector<int> freq(n + 1, 0);
    std::vector<std::vector<int>> pos(3);
    int[][][] dp;

    // Since C++ doesn't allow variable length multi-dimensional arrays easily,
    // We'll use a map or 4D vector for dp, but for simplicity, use maps or resize accordingly.
    // To optimize, we'll create a 4D vector after total counts are available.

    // Count variables
    int totalV = 0, totalK = 0, totalS = 0;

    // Count frequencies and populate pos
    std::vector<std::vector<int>> freq_list(n + 1, std::vector<int>(3,0));

    int idx = 0;
    for (char x : c) {
        if (x == 'V') {
            totalV++;
            freq[idx + 1][0]++;
            pos[0].push_back(idx + 1);
        } else if (x == 'K') {
            totalK++;
            freq[idx + 1][1]++;
            pos[1].push_back(idx + 1);
        } else {
            totalS++;
            freq[idx + 1][2]++;
            pos[2].push_back(idx + 1);
        }
        for (int i=0; i<3; i++) {
            freq_list[idx + 1][i] = freq_list[idx][i] + (x == 'V' ? 1 : 0) * (i==0) + (x == 'K' ? 1 : 0) * (i==1) + (x == 'S' ? 1 : 0) * (i==2);
        }
        idx++;
    }

    // Prepare DP array
    int maxV = totalV, maxK = totalK, maxS = totalS;
    std::vector<std::vector<std::vector<std::vector<int>>>> dp(
        maxV + 1, std::vector<std::vector<std::vector<int>>>(maxK + 1, std::vector<std::vector<int>>(maxS + 1, std::vector<int>(3, -1)))
    );

    // The recursive DFS function
    std::function<int(int,int,int,int)> dfs = [&](int tv, int tk, int ts, int last) -> int {
        if (tv == maxV && tk == maxK && ts == maxS)
            return 0;
        if (dp[tv][tk][ts][last] != -1)
            return dp[tv][tk][ts][last];
        int ret = 1 << 29;

        auto calc_move = [&](int p) {
            int move = 0;
            move += std::max(freq_list[p][0] - tv, 0);
            move += std::max(freq_list[p][1] - tk, 0);
            move += std::max(freq_list[p][2] - ts, 0);
            return move - 1;
        };

        if (tv < maxV) {
            int p = pos[0][tv];
            int move = calc_move(p);
            ret = std::min(ret, dfs(tv + 1, tk, ts, 0) + move);
        }
        if (tk < maxK && last != 0) {
            int p = pos[1][tk];
            int move = calc_move(p);
            ret = std::min(ret, dfs(tv, tk + 1, ts, 1) + move);
        }
        if (ts < maxS) {
            int p = pos[2][ts];
            int move = calc_move(p);
            ret = std::min(ret, dfs(tv, tk, ts + 1, 2) + move);
        }
        return dp[tv][tk][ts][last] = ret;
    };

    out.println(dfs(0, 0, 0, 2));

    return 0;
}

